after(async () => { await harness?.stop(); for (const name of ['FINITUDE_ADMIN_IMPORTS_ENABLED', 'FINITUDE_ADMIN_IMPORT_PRIVATE_STORAGE_READY', 'ADMIN_IMPORT_S3_BUCKET_NAME', 'S3_BUCKET_NAME']) delete process.env[name]; });

const mutation = (expectedRevision: number) => ({ operationId: randomUUID(), expectedRevision });
const code = (expected: string) => (error: unknown) => error instanceof AdminImportError && error.code === expected;
const stored = async (id: string) => (await getDb()!.collection<AdminImportDocument>('adminAlbumImports').findOne({ _id: new ObjectId(id) }))!;
const sha = (bytes: Buffer) => createHash('sha256').update(bytes).digest('hex');
const pngOf = (background: string) => sharp({ create: { width: 2, height: 2, channels: 3, background } }).png().toBuffer();
/** A short silent WAV whose first sample differs per call, so no two files share their bytes. */
let sample = 0;
const wav = () => { const value = Buffer.alloc(16044); value.writeUInt16LE(++sample % 65_536, 44); value.write('RIFF', 0); value.writeUInt32LE(16036, 4); value.write('WAVEfmt ', 8); value.writeUInt32LE(16, 16); value.writeUInt16LE(1, 20); value.writeUInt16LE(1, 22); value.writeUInt32LE(8000, 24); value.writeUInt32LE(16000, 28); value.writeUInt16LE(2, 32); value.writeUInt16LE(16, 34); value.write('data', 36); value.writeUInt32LE(16000, 40); return value; };
/** A WAV whose RIFF `id3 ` chunk carries one front-cover APIC frame with the given image bytes. */
function taggedWav(image: Buffer) {
    const apic = Buffer.concat([Buffer.from([3]), Buffer.from('image/png\0'), Buffer.from([3, 0]), image]), frame = Buffer.alloc(10); frame.write('APIC'); frame.writeUInt32BE(apic.length, 4);
    const tags = Buffer.concat([frame, apic]), id3 = Buffer.from([73, 68, 51, 3, 0, 0, 0, 0, 0, 0]); for (let i = 0; i < 4; i++) id3[9 - i] = (tags.length >>> (i * 7)) & 127;
    const chunk = Buffer.alloc(8); chunk.write('id3 '); chunk.writeUInt32LE(id3.length + tags.length, 4);
    const bytes = Buffer.concat([wav(), chunk, id3, tags, ...((id3.length + tags.length) % 2 ? [Buffer.alloc(1)] : [])]); bytes.writeUInt32LE(bytes.length - 8, 4); return bytes;
}
/** A folderless import of `count` files whose sizes stay open, so any audio may fill a slot. */
async function project(count: number) {
    const slots = Array.from({ length: count }, () => randomUUID());
    const created = await createAdminImport(actor.toHexString(), { operationId: randomUUID(), manifest: { rootLabel: 'Synthetic Album', files: slots.map((slotId, i) => ({ slotId, filename: `Track ${i + 1}.wav`, relativePath: `Track ${i + 1}.wav`, byteLength: null })) } });
    return { id: created.item.id, slots };
}
const audio = (index: number, bytes: Buffer) => ({ fieldname: 'file', originalname: `Track ${index + 1}.wav`, mimetype: 'audio/wav', size: bytes.length, buffer: bytes, encoding: '7bit' } as Express.Multer.File);
const upload = (target: { id: string; slots: string[] }, index: number, bytes: Buffer, storage: Storage, intent = mutation(1), by = actor) =>
    uploadAdminImportAsset(by.toHexString(), target.id, target.slots[index], intent, audio(index, bytes), storage);
const choice = (item: { coverChoice: string; selectedCoverSlotId: string | null }) => [item.coverChoice, item.selectedCoverSlotId];
const asset = (doc: AdminImportDocument, slotId: string) => doc.media!.assets.find(value => value.slotId === slotId)!;
const fresh = (scope: string, slotId: string | null = null) => ({ scope, slotId, entryKey: null as string | null, boundName: null as string | null, action: 'create-distinct', candidateId: null as string | null, candidateRevision: null as string | null });
const distinctAll = (item: { draft: ImportDraftV2 }) => [...item.draft.album.artists.map(entry => ({ ...fresh('artist'), entryKey: entry.key, boundName: entry.name })), fresh('album'), ...item.draft.tracks.map(track => fresh('track', track.slotId))];
/** Names the Album, its Artist and every track, as an administrator does before approving. */
async function named(id: string) {
    const { item } = await getAdminImport(actor.toHexString(), id);
    return (await editImportDraft(actor.toHexString(), id, item, draft => { Object.assign(draft.album, { title: 'Synthetic Album', artists: artistEntries('Synthetic Artist') }); draft.tracks.forEach((track, i) => { track.title = `Synthetic ${i + 1}`; track.trackNumber = i + 1; }); })).item;
}
/** Approves the named project as its confirmation shows it, with a new identity for everything unless `options` say otherwise. */
async function approve(id: string, options: ApprovalOptions = {}) { const item = await named(id); return publishAdminImport(actor.toHexString(), id, approvalBody(item, { decisions: distinctAll(item), ...options })); }
/** Stores a frozen fixture with its staged objects; its publisher holds `role`. */
async function fixture(storage: Storage, name: string, role = 'admin', change?: (doc: AdminImportDocument) => void) {
    await getDb()!.collection('users').updateOne({ _id: fixtureAdmin }, { $set: { email: 'fixture-admin@example.test', role } }, { upsert: true });
    const doc = loadImportFixture('adminImport', name), id = doc._id.toHexString(); change?.(doc); storage.seed(doc.media!.assets);
    await getDb()!.collection<AdminImportDocument>('adminAlbumImports').insertOne(doc); return { id, doc };
}
const embeddedOf = (doc: AdminImportDocument) => doc.media!.assets.filter(value => value.slotId.startsWith('embedded-'));

test('each confirmed audio upload records the digest of the image it carries at admission; none or an invalid image records null, and a replay keeps it', async () => {
    const storage = new Storage(), target = await project(3), png = await pngOf('#fa8'), intent = mutation(1), tagged = taggedWav(png);
    await upload(target, 0, tagged, storage, intent); await upload(target, 1, wav(), storage); await upload(target, 2, taggedWav(Buffer.from('not an image at all')), storage);
    let doc = await stored(target.id);
    assert.deepEqual(target.slots.map(slot => asset(doc, slot).artworkSha256), [sha(png), null, null]);
    assert.equal(asset(doc, `embedded-${target.slots[0]}`).sha256, sha(png)); assert.equal(embeddedOf(doc).length, 1);
    const replay = await upload(target, 0, tagged, storage, intent); doc = await stored(target.id);
    assert.equal(asset(doc, target.slots[0]).artworkSha256, sha(png)); assert.equal(replay.receipt!.operationId, intent.operationId);
    // A manual cover is no audio upload and carries no evidence; the projection never shows it.
    const cover = await uploadAdminImportAsset(actor.toHexString(), target.id, 'cover', mutation(1), { ...audio(0, png), originalname: 'cover.png', mimetype: 'image/png' }, storage);
    assert.equal('artworkSha256' in asset(await stored(target.id), 'cover'), false); assert.equal(JSON.stringify(cover.item).includes('artworkSha256'), false);
});

test('the image every confirmed file shares is chosen automatically, takes no receipt, and is re-evaluated as the file set changes', async () => {
    const storage = new Storage(), target = await project(3), [x, y] = [await pngOf('#fa8'), await pngOf('#08a')], first = `embedded-${target.slots[0]}`;
    assert.deepEqual(choice((await upload(target, 0, taggedWav(x), storage)).item), ['automatic', first]);
    // The second file's identical image is staged once, so the first file's candidate stays the one chosen.
    const second = await upload(target, 1, taggedWav(x), storage); assert.deepEqual(choice(second.item), ['automatic', first]);
    assert.equal(second.item.assets.some(value => value.slotId === `embedded-${target.slots[1]}`), false);
    let item = (await upload(target, 2, taggedWav(y), storage)).item; assert.deepEqual(choice(item), ['automatic', null]);
    item = (await cleanupAdminImportAsset(actor.toHexString(), target.id, target.slots[2], mutation(item.revision), storage)).item; assert.deepEqual(choice(item), ['automatic', first]);
    item = (await upload(target, 2, wav(), storage)).item; assert.deepEqual(choice(item), ['automatic', null]);
    const doc = await stored(target.id);
    assert.equal(doc.receipts.some(receipt => receipt.kind === 'select-cover'), false); assert.equal('selectedCoverSlotId' in doc.media!, false);
    // The approval digest covers the shown automatic choice.
    const restored = (await cleanupAdminImportAsset(actor.toHexString(), target.id, target.slots[2], mutation(item.revision), storage)).item;
    assert.notEqual(restored.approvalDigest, item.approvalDigest); assert.equal(restored.selectedCoverSlotId, first);
});

test('an explicit choice, including No cover, wins and stays explicit while files change; removing the chosen image leaves explicit No cover', async () => {
    const storage = new Storage(), target = await project(3), [x, y] = [await pngOf('#fa8'), await pngOf('#08a')], first = `embedded-${target.slots[0]}`;
    let item = (await upload(target, 0, taggedWav(x), storage)).item;
    item = (await selectAdminImportCover(actor.toHexString(), target.id, { ...mutation(item.revision), slotId: null })).item; assert.deepEqual(choice(item), ['explicit', null]);
    item = (await upload(target, 1, taggedWav(x), storage)).item; assert.deepEqual(choice(item), ['explicit', null]);
    item = (await selectAdminImportCover(actor.toHexString(), target.id, { ...mutation(item.revision), slotId: first })).item; assert.deepEqual(choice(item), ['explicit', first]);
    item = (await upload(target, 2, taggedWav(y), storage)).item; assert.deepEqual(choice(item), ['explicit', first]);
    item = (await cleanupAdminImportAsset(actor.toHexString(), target.id, first, mutation(item.revision), storage)).item; assert.deepEqual(choice(item), ['explicit', null]);
    assert.equal((await stored(target.id)).media!.selectedCoverSlotId, null);
});

test('an Album decision of skip deselects the automatic cover, and create selects it again', async () => {
    const storage = new Storage(), target = await project(1), first = `embedded-${target.slots[0]}`;
    let item = (await upload(target, 0, taggedWav(await pngOf('#fa8')), storage)).item; assert.deepEqual(choice(item), ['automatic', first]);
    item = (await decideAdminImportDuplicates(actor.toHexString(), target.id, { ...mutation(item.revision), decisions: [{ ...fresh('album'), action: 'skip' }] })).item;
    assert.deepEqual(choice(item), ['automatic', null]);
    item = (await decideAdminImportDuplicates(actor.toHexString(), target.id, { ...mutation(item.revision), decisions: [fresh('album')] })).item;
    assert.deepEqual(choice(item), ['automatic', first]);
});

test('a shared image whose staging outcome is unknown is chosen once reconciliation confirms it under the automatic intent', async () => {
    const storage = new Storage(), target = await project(2), x = await pngOf('#fa8'), first = `embedded-${target.slots[0]}`; storage.failEmbeddedPut = true;
    await upload(target, 0, taggedWav(x), storage); let item = (await upload(target, 1, taggedWav(x), storage)).item;
    assert.equal(item.assets.find(value => value.slotId === first)!.state, 'unknown'); assert.deepEqual(choice(item), ['automatic', null]);
    const doc = await stored(target.id), staged = asset(doc, first); assert.equal(doc.automaticReceipts![0].operationId, staged.operationId);
    storage.failEmbeddedPut = false; storage.objects.set(`${staged.bucket}/${staged.key}`, { etag: '"late-etag"', versionId: 'late-version' });
    item = (await reconcileAdminImportAsset(other.toHexString(), target.id, first, { operationId: staged.operationId }, storage)).item;
    assert.equal(item.assets.find(value => value.slotId === first)!.state, 'ready'); assert.deepEqual(choice(item), ['automatic', first]);
});

test('a shared image the staging bound kept out selects nothing, while its evidence is still recorded', async () => {
    const storage = new Storage(), target = await project(2), x = await pngOf('#fa8'), at = new Date();
    const seeded = Array.from({ length: 16 }, () => ({ operationId: randomUUID(), kind: 'upload', revision: 1, actorId: actor.toHexString(), hash: 'a'.repeat(64), at }));
    await getDb()!.collection('adminAlbumImports').updateOne({ _id: new ObjectId(target.id) }, { $set: { automaticReceipts: seeded } });
    await upload(target, 0, taggedWav(x), storage); const item = (await upload(target, 1, taggedWav(x), storage)).item, doc = await stored(target.id);
    assert.deepEqual(choice(item), ['automatic', null]); assert.equal(embeddedOf(doc).length, 0);
    assert.deepEqual(target.slots.map(slot => asset(doc, slot).artworkSha256), [sha(x), sha(x)]);
});

test('approving the shown automatic cover freezes it and keeps the choice automatic; showing No cover is explicit; an append freezes none', async () => {
    const storage = new Storage(), target = await project(2), x = await pngOf('#fa8'), first = `embedded-${target.slots[0]}`;
    await upload(target, 0, taggedWav(x), storage); await upload(target, 1, taggedWav(x), storage);
    const approved = await approve(target.id); let doc = await stored(target.id);
    assert.equal(doc.media!.publication!.cover!.slotId, first); assert.equal('selectedCoverSlotId' in doc.media!, false); assert.deepEqual(choice(approved.item), ['automatic', first]);
    // Cancelled and cleaned, the next approval shows No cover instead: that is an explicit choice, and no cover is frozen.
    await cancelAdminImportPublication(actor.toHexString(), target.id, { ...mutation(approved.item.revision), publicationOperationId: doc.media!.publication!.operationId }, storage);
    const cancelled = await getAdminImport(actor.toHexString(), target.id); assert.equal(cancelled.item.publicationRecovery!.cleanupPending, false);
    const second = await publishAdminImport(actor.toHexString(), target.id, approvalBody(cancelled.item, { decisions: distinctAll(cancelled.item), selectedCoverSlotId: null }));
    doc = await stored(target.id); assert.deepEqual([doc.media!.selectedCoverSlotId, doc.media!.publication!.cover], [null, null]); assert.deepEqual(choice(second.item), ['explicit', null]);
    // An approval whose own decisions append to an existing Album shows the automatic cover, freezes none and stays automatic.
    await runAdminImportPublicationOnce(storage, target.id); const existing = (await getAdminImport(actor.toHexString(), target.id)).item.published!;
    const appending = await project(2), z = await pngOf('#888'); await upload(appending, 0, taggedWav(z), storage); await upload(appending, 1, taggedWav(z), storage);
    const item = await named(appending.id), candidates = (await adminImportDuplicateCandidates(actor.toHexString(), appending.id)).items;
    const reuse = (scope: 'artist' | 'album', id: string) => ({ ...fresh(scope), action: 'reuse', candidateId: id, candidateRevision: candidates.find(value => value.kind === scope && value.id === id)!.revision });
    assert.equal(item.selectedCoverSlotId, `embedded-${appending.slots[0]}`);
    const appended = await publishAdminImport(actor.toHexString(), appending.id, approvalBody(item, { decisions: withEntryKeys(item.draft, [reuse('artist', existing.artistIds[0]), reuse('album', existing.albumId), ...appending.slots.map(slot => fresh('track', slot))]) }));
    doc = await stored(appending.id);
    assert.deepEqual([doc.media!.publication!.cover, doc.media!.publication!.newAlbum, 'selectedCoverSlotId' in doc.media!], [null, false, false]); assert.deepEqual(choice(appended.item), ['automatic', null]);
    // Completing the append cleans its unselected candidate.
    await runAdminImportPublicationOnce(storage, appending.id); assert.equal(asset(await stored(appending.id), `embedded-${appending.slots[0]}`).state, 'deleted');
});

test('completion cleans every unselected automatic candidate through the cleanup lifecycle, keeping the selected cover, the audio and a manual cover', async () => {
    const storage = new Storage(), target = await project(3), images = [await pngOf('#fa8'), await pngOf('#08a'), await pngOf('#8a0')];
    for (const [index, image] of images.entries()) await upload(target, index, taggedWav(image), storage);
    const covered = await uploadAdminImportAsset(actor.toHexString(), target.id, 'cover', mutation(1), { ...audio(0, images[0]), originalname: 'cover.png', mimetype: 'image/png' }, storage);
    assert.deepEqual(choice(covered.item), ['automatic', null]);
    await selectAdminImportCover(actor.toHexString(), target.id, { ...mutation(covered.item.revision), slotId: 'cover' }); await approve(target.id);
    const before = await stored(target.id), deletes = storage.deletes; assert.equal(await runAdminImportPublicationOnce(storage, target.id), true);
    const doc = await stored(target.id), candidates = embeddedOf(doc);
    assert.equal(doc.media!.publication!.state, 'complete'); assert.deepEqual(candidates.map(value => value.state), ['deleted', 'deleted', 'deleted']);
    assert.equal(storage.deletes - deletes, 3); assert.equal(candidates.some(value => storage.has(target.id, value)), false);
    for (const slot of [...target.slots, 'cover']) { assert.equal(asset(doc, slot).state, 'ready', slot); assert.equal(storage.has(target.id, asset(doc, slot)), true, slot); }
    // Each reservation is an automatic cleanup receipt under the UUID derived from the candidate version, naming the publisher.
    const added = doc.automaticReceipts!.slice(before.automaticReceipts!.length);
    assert.deepEqual(added.map(receipt => [receipt.kind, receipt.operationId, receipt.actorId]), candidates.map(value => ['cleanup', automaticCoverCleanupOperationId(value), actor.toHexString()]));
    assert.deepEqual(candidates.map(value => value.recovery), added.map(receipt => ({ operationId: receipt.operationId, expectedRevision: receipt.revision - 1, kind: 'cleanup', actorId: actor.toHexString() })));
    assert.deepEqual([doc.receipts, doc.recoveryReceipts], [before.receipts, before.recoveryReceipts]);
    assert.equal(doc.media!.coverCleanup!.state, 'done'); assert.equal(await runAutomaticImportCoverCleanupOnce(storage), false);
    // When the automatic image itself was published, nothing else is cleaned.
    const shared = await project(2), x = await pngOf('#a08'); await upload(shared, 0, taggedWav(x), storage); await upload(shared, 1, taggedWav(x), storage);
    await approve(shared.id); const count = storage.deletes; await runAdminImportPublicationOnce(storage, shared.id);
    const published = await stored(shared.id); assert.equal(storage.deletes, count); assert.deepEqual(embeddedOf(published).map(value => value.state), ['ready']);
    assert.equal(published.media!.coverCleanup!.state, 'done');
});

/** A completed import of two files with distinct images, so both candidates are unselected at completion. */
async function completedWithCandidates(storage: Storage, prepare?: () => void) {
    const target = await project(2); await upload(target, 0, taggedWav(await pngOf('#fa8')), storage); await upload(target, 1, taggedWav(await pngOf('#08a')), storage);
    await approve(target.id); prepare?.(); await runAdminImportPublicationOnce(storage, target.id); return { target, doc: await stored(target.id) };
}
test('a failed automatic cleanup needs attention, and any current administrator retries it with the original intent', async () => {
    const storage = new Storage(), { target, doc } = await completedWithCandidates(storage, () => { storage.failDelete = true; }), [failed] = embeddedOf(doc);
    assert.deepEqual(embeddedOf(doc).map(value => value.state), ['cleanupFailed', 'cleanupFailed']); assert.equal(doc.media!.publication!.state, 'complete');
    assert.equal((await listAdminImports(other.toHexString(), { filter: 'needsAttention' })).counts.needsAttention, 1);
    await assert.rejects(cleanupAdminImportAsset(other.toHexString(), target.id, failed.slotId, mutation(doc.revision), storage), code('ADMIN_IMPORT_ASSET_CLEANUP_EXISTS'));
    storage.failDelete = false;
    const intent = { operationId: failed.recovery.operationId, expectedRevision: failed.recovery.expectedRevision };
    const retried = await cleanupAdminImportAsset(other.toHexString(), target.id, failed.slotId, intent, storage), after = await stored(target.id);
    assert.equal(asset(after, failed.slotId).state, 'deleted'); assert.equal(storage.has(target.id, failed), false);
    assert.deepEqual([after.receipts.length, after.recoveryReceipts?.length ?? 0, after.automaticReceipts!.length], [doc.receipts.length, doc.recoveryReceipts?.length ?? 0, doc.automaticReceipts!.length]);
    assert.deepEqual(retried.receipt, { operationId: intent.operationId, kind: 'cleanup', revision: intent.expectedRevision + 1 });
    assert.deepEqual((await cleanupAdminImportAsset(other.toHexString(), target.id, failed.slotId, intent, storage)).receipt, retried.receipt);
});

