test('imports completed before automatic covers are swept once, cleaning their unselected per-file candidates', async () => {
    const storage = new Storage(), complete = await fixture(storage, completeName), append = await fixture(storage, appendName);
    assert.equal(await runAutomaticImportCoverCleanupOnce(storage), true); assert.equal(await runAutomaticImportCoverCleanupOnce(storage), true);
    assert.equal(await runAutomaticImportCoverCleanupOnce(storage), false);
    // The selected and published candidate stays; an append selected none, so both of its candidates go.
    assert.deepEqual(embeddedOf(await stored(complete.id)).map(value => value.state), ['deleted', 'ready']);
    assert.deepEqual(embeddedOf(await stored(append.id)).map(value => value.state), ['deleted', 'deleted']); assert.equal(storage.deletes, 3);
    // The sweep is off while imports are disabled or storage is not ready, except for the pass a publication runs itself.
    await getDb()!.collection('adminAlbumImports').updateMany({}, { $unset: { 'media.coverCleanup': '' } }); process.env.FINITUDE_ADMIN_IMPORT_PRIVATE_STORAGE_READY = 'false';
    assert.equal(await runAutomaticImportCoverCleanupOnce(storage), false); assert.equal(await runAutomaticImportCoverCleanupOnce(storage, complete.id), true);
});

test('a candidate still in its transfer window waits for it to settle', async () => {
    const storage = new Storage(), now = new Date(), deadline = new Date(now.getTime() + 60_000);
    const { id, doc } = await fixture(storage, completeName, 'admin', value => { Object.assign(value.media!.assets.find(item => item.slotId.startsWith('embedded-'))!, { state: 'unknown', etag: null, versionId: null, transferDeadline: deadline }); });
    const [waiting] = embeddedOf(doc), before = await stored(id);
    assert.equal(await runAutomaticImportCoverCleanupOnce(storage, undefined, undefined, now), true);
    let after = await stored(id);
    assert.deepEqual([asset(after, waiting.slotId).state, after.media!.coverCleanup, after.revision], ['unknown', { state: 'pending', leaseOwner: null, leaseUntil: deadline }, before.revision]);
    assert.equal(await runAutomaticImportCoverCleanupOnce(storage, undefined, undefined, now), false);
    assert.equal(await runAutomaticImportCoverCleanupOnce(storage, undefined, undefined, new Date(deadline.getTime() + 1)), true);
    after = await stored(id); assert.equal(asset(after, waiting.slotId).state, 'deleted'); assert.equal(storage.has(id, waiting), false); assert.equal(after.media!.coverCleanup!.state, 'done');
});

test('a pass stopped between deletions resumes the same intents once its lease expires', async () => {
    const storage = new Storage(), now = new Date(), stop = new AbortController(), { id, doc } = await fixture(storage, appendName);
    storage.afterDelete = () => stop.abort();
    assert.equal(await runAutomaticImportCoverCleanupOnce(storage, undefined, stop.signal, now), true);
    const halfway = await stored(id); assert.deepEqual(embeddedOf(halfway).map(value => value.state), ['deleted', 'deleting']); assert.equal(storage.deletes, 1);
    const intents = embeddedOf(halfway).map(value => value.recovery.operationId);
    // The lease still holds it, then a later pass deletes the rest under the intents already reserved.
    storage.afterDelete = undefined; assert.equal(await runAutomaticImportCoverCleanupOnce(storage, undefined, undefined, new Date(now.getTime() + 60_000)), false);
    assert.equal(await runAutomaticImportCoverCleanupOnce(storage, undefined, undefined, new Date(now.getTime() + 305_000)), true);
    const done = await stored(id);
    assert.deepEqual(embeddedOf(done).map(value => [value.state, value.recovery.operationId]), intents.map(intent => ['deleted', intent])); assert.equal(storage.deletes, 2);
    assert.deepEqual(done.automaticReceipts!.map(receipt => receipt.operationId), intents); assert.equal(embeddedOf(doc).every((value, i) => automaticCoverCleanupOperationId(value) === intents[i]), true);
});

test('no automatic cleanup runs for an active or cancelled publication, a newer-format project or a catalog review', async () => {
    const storage = new Storage();
    const cases: [string, ((doc: AdminImportDocument) => void) | undefined][] = [['v1-publication-preparing.json', undefined], ['v1-publication-needs-attention.json', undefined],
        ['v1-publication-cancelled-cleanup-pending.json', undefined], [completeName, doc => { doc.draftVersion = 3; }], [appendName, doc => { doc.purpose = 'catalogReview'; }]];
    const ids: string[] = []; for (const [name, change] of cases) ids.push((await fixture(storage, name, 'admin', change)).id);
    const before = await Promise.all(ids.map(stored));
    assert.equal(await runAutomaticImportCoverCleanupOnce(storage), false);
    for (const id of ids) assert.equal(await runAutomaticImportCoverCleanupOnce(storage, id), false);
    assert.deepEqual(await Promise.all(ids.map(stored)), before); assert.equal(storage.deletes, 0);
    // The staging UUID formula is unchanged, so these frozen candidates keep their intents.
    for (const doc of before) for (const value of embeddedOf(doc)) assert.equal(value.operationId, embeddedImportOperationId(asset(doc, value.slotId.slice(9)).operationId, value.slotId.slice(9)));
});

