test('replacing the only file with one carrying another image cleans the old candidate first and selects the new image', async () => {
    const storage = new Storage(), target = await project(1), first = `embedded-${target.slots[0]}`, y = await pngOf('#08a');
    let item = (await upload(target, 0, taggedWav(await pngOf('#fa8')), storage)).item; assert.deepEqual(choice(item), ['automatic', first]);
    const old = asset(await stored(target.id), first), cleanupId = automaticCoverCleanupOperationId(old);
    item = (await cleanupAdminImportAsset(actor.toHexString(), target.id, target.slots[0], mutation(item.revision), storage)).item; assert.deepEqual(choice(item), ['automatic', null]);
    const before = await stored(target.id); item = (await upload(target, 0, taggedWav(y), storage, mutation(1), other)).item;
    const doc = await stored(target.id), staged = asset(doc, first);
    assert.deepEqual(choice(item), ['automatic', first]); assert.equal(staged.sha256, sha(y)); assert.equal(storage.has(target.id, staged), true);
    // The old candidate went through the cleanup lifecycle under an automatic receipt naming the uploader, and stays in history.
    const cleaned = doc.media!.assetHistory!.find(value => value.slotId === first && value.operationId === old.operationId)!, added = doc.automaticReceipts!.slice(before.automaticReceipts!.length);
    assert.deepEqual(added.map(receipt => [receipt.kind, receipt.operationId, receipt.actorId]), [['cleanup', cleanupId, other.toHexString()], ['upload', staged.operationId, other.toHexString()]]);
    assert.deepEqual([cleaned.state, cleaned.recovery], ['deleted', { operationId: cleanupId, expectedRevision: added[0].revision - 1, kind: 'cleanup', actorId: other.toHexString() }]);
    assert.equal(storage.has(target.id, old), false);
    assert.deepEqual([doc.receipts.length, doc.recoveryReceipts!.length], [before.receipts.length + 1, before.recoveryReceipts!.length]);
    // Completion keeps the new image it published.
    await approve(target.id); await runAdminImportPublicationOnce(storage, target.id);
    assert.deepEqual([asset(await stored(target.id), first).state, (await stored(target.id)).media!.publication!.cover!.slotId], ['ready', first]);
});

test('a replaced candidate whose image another file still carries is kept, and the last file replaced stages the new shared image', async () => {
    const storage = new Storage(), target = await project(2), [x, y] = [await pngOf('#fa8'), await pngOf('#08a')], [first, second] = target.slots.map(slot => `embedded-${slot}`);
    await upload(target, 0, taggedWav(x), storage); let item = (await upload(target, 1, taggedWav(x), storage)).item; assert.deepEqual(choice(item), ['automatic', first]);
    item = (await cleanupAdminImportAsset(actor.toHexString(), target.id, target.slots[0], mutation(item.revision), storage)).item;
    const deletes = storage.deletes; item = (await upload(target, 0, taggedWav(y), storage)).item; let doc = await stored(target.id);
    assert.deepEqual([asset(doc, first).sha256, asset(doc, first).state, choice(item)], [sha(x), 'ready', ['automatic', null]]); assert.equal(storage.deletes, deletes);
    item = (await cleanupAdminImportAsset(actor.toHexString(), target.id, target.slots[1], mutation(item.revision), storage)).item;
    item = (await upload(target, 1, taggedWav(y), storage)).item; doc = await stored(target.id);
    assert.deepEqual([asset(doc, second).sha256, choice(item)], [sha(y), ['automatic', second]]); assert.equal(asset(doc, first).state, 'ready');
});

test('a failed cleanup of a replaced candidate needs attention and leaves the new image unstaged, and a stopped one is resumed by the next staging', async () => {
    const storage = new Storage(), target = await project(1), first = `embedded-${target.slots[0]}`, [x, y] = [await pngOf('#fa8'), await pngOf('#08a')];
    let item = (await upload(target, 0, taggedWav(x), storage)).item;
    item = (await cleanupAdminImportAsset(actor.toHexString(), target.id, target.slots[0], mutation(item.revision), storage)).item;
    storage.failDelete = true; item = (await upload(target, 0, taggedWav(y), storage)).item; storage.failDelete = false;
    const failed = asset(await stored(target.id), first);
    assert.deepEqual([failed.state, failed.sha256, choice(item)], ['cleanupFailed', sha(x), ['automatic', null]]);
    assert.equal((await listAdminImports(other.toHexString(), { filter: 'needsAttention' })).counts.needsAttention, 1);
    await cleanupAdminImportAsset(other.toHexString(), target.id, first, { operationId: failed.recovery.operationId, expectedRevision: failed.recovery.expectedRevision }, storage);
    assert.equal(asset(await stored(target.id), first).state, 'deleted');
    // A staging stopped after its reservation leaves the candidate deleting under the derived intent; the next staging resumes it.
    const resumed = await project(1), slot = `embedded-${resumed.slots[0]}`;
    item = (await upload(resumed, 0, taggedWav(x), storage)).item;
    item = (await cleanupAdminImportAsset(actor.toHexString(), resumed.id, resumed.slots[0], mutation(item.revision), storage)).item;
    const reserved = asset(await stored(resumed.id), slot), cleanupId = automaticCoverCleanupOperationId(reserved);
    await getDb()!.collection('adminAlbumImports').updateOne({ _id: new ObjectId(resumed.id), 'media.assets.slotId': slot }, { $set: { 'media.assets.$.state': 'deleting',
        'media.assets.$.recovery': { operationId: cleanupId, expectedRevision: item.revision, kind: 'cleanup', actorId: actor.toHexString() } } });
    item = (await upload(resumed, 0, taggedWav(y), storage)).item; const doc = await stored(resumed.id);
    assert.deepEqual([asset(doc, slot).sha256, choice(item)], [sha(y), ['automatic', slot]]); assert.equal(storage.has(resumed.id, reserved), false);
    assert.equal(doc.media!.assetHistory!.find(value => value.operationId === reserved.operationId)!.state, 'deleted');
});

