test('the publication worker sweeps a completed import on a tick that publishes nothing', async () => {
    const storage = new Storage(), { id } = await fixture(storage, appendName), stop = startAdminImportPublisher(storage, 20);
    try { for (let i = 0; i < 200 && (await stored(id)).media!.coverCleanup?.state !== 'done'; i++) await new Promise(resolve => setTimeout(resolve, 25)); }
    finally { await stop(); }
    const doc = await stored(id); assert.equal(doc.media!.coverCleanup!.state, 'done');
    assert.deepEqual(embeddedOf(doc).map(value => value.state), ['deleted', 'deleted']); assert.equal(storage.deletes, 2);
});
